'use strict';

function compareCatalogs(referenceEntries, candidateEntries, done) {
  if (typeof done !== 'function') {
    throw new TypeError('done must be a function');
  }

  queueMicrotask(() => {
    try {
      const reference = indexCatalog(referenceEntries, 'referenceEntries');
      const candidate = indexCatalog(candidateEntries, 'candidateEntries');

      for (const [name, body] of reference) {
        if (!candidate.has(name) || candidate.get(name) !== body) {
          done(null, false);
          return;
        }
      }

      done(null, true);
    } catch (error) {
      done(error);
    }
  });
}

function indexCatalog(entries, label) {
  if (!Array.isArray(entries)) {
    throw new TypeError(label + ' must be an array');
  }

  const result = new Map();
  for (const entry of entries) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new TypeError(label + ' must contain records');
    }
    if (typeof entry.name !== 'string' || entry.name.length === 0) {
      throw new TypeError('entry name must be a non-empty string');
    }
    if (typeof entry.body !== 'string') {
      throw new TypeError('entry body must be a string');
    }
    if (result.has(entry.name)) {
      throw new Error('duplicate entry name: ' + entry.name);
    }
    result.set(entry.name, entry.body);
  }
  return result;
}

module.exports = { compareCatalogs };

