'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['compareCatalogs']);
const { compareCatalogs } = api;
assert.equal(typeof compareCatalogs, 'function');

assert.throws(() => compareCatalogs([], [], null), TypeError);

function compare(reference, candidate) {
  return new Promise((resolve, reject) => {
    let synchronous = true;
    let calls = 0;
    compareCatalogs(reference, candidate, (error, result) => {
      calls += 1;
      try {
        assert.equal(synchronous, false, 'callback must be asynchronous');
      } catch (failure) {
        reject(failure);
        return;
      }
      setImmediate(() => resolve({ error, result, calls }));
    });
    synchronous = false;
  });
}

(async () => {
  const empty = await compare([], []);
  assert.equal(empty.error, null);
  assert.equal(empty.result, true);
  assert.equal(empty.calls, 1);

  const reference = Object.freeze([
    Object.freeze({ name: 'alpha', body: 'A' }),
    Object.freeze({ name: 'beta', body: 'B' })
  ]);
  const candidate = Object.freeze([
    Object.freeze({ name: 'beta', body: 'B' }),
    Object.freeze({ name: 'alpha', body: 'A' })
  ]);
  assert.deepEqual(await compare(reference, candidate), { error: null, result: true, calls: 1 });

  assert.equal((await compare(reference, [{ name: 'alpha', body: 'A' }])).result, false);
  assert.equal((await compare(reference, [...candidate, { name: 'gamma', body: 'C' }])).result, false);
  assert.equal((await compare(reference, [{ name: 'alpha', body: 'a' }, { name: 'beta', body: 'B' }])).result, false);
  assert.equal((await compare(reference, [{ name: 'alpha', body: 'A' }, { name: 'gamma', body: 'B' }])).result, false);

  for (const [left, right] of [
    [null, []],
    [[], 'catalog'],
    [[{ name: '', body: 'x' }], []],
    [[{ name: 'x', body: 1 }], []],
    [[{ name: 'x', body: 'a' }, { name: 'x', body: 'b' }], []],
    [[], [{ name: 'x', body: 'a' }, { name: 'x', body: 'a' }]]
  ]) {
    const outcome = await compare(left, right);
    assert.ok(outcome.error instanceof Error);
    assert.equal(outcome.calls, 1);
  }
})().catch((error) => {
  process.nextTick(() => { throw error; });
});

